changeSet.sql:
UPDATE bng.projects
   SET last_modified_by = user_id
 WHERE last_modified_by IS NULL;

changeSet.rollback:
CREATE OR REPLACE FUNCTION bng.write_projects_audit_log()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO bng.audit_log (
        project_id, project, user_id, bng_project_version, operation, audited_at
    ) VALUES (
        NEW.id, NEW.project, NEW.user_id, NEW.bng_project_version, TG_OP, CURRENT_TIMESTAMP
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

rollback.sql:
CREATE OR REPLACE FUNCTION bng.write_projects_audit_log()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO bng.audit_log (
        project_id, project, user_id, bng_project_version, operation, audited_at
    ) VALUES (
        NEW.id, NEW.project, NEW.last_modified_by, NEW.bng_project_version, TG_OP, CURRENT_TIMESTAMP
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

changeSet.sql:
CREATE OR REPLACE FUNCTION bng.reject_unaudited_project_delete()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION
        'bng.projects deletion requires an audited deletion workflow'
        USING ERRCODE = 'insufficient_privilege';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER projects_reject_unaudited_delete
    BEFORE DELETE ON bng.projects
    FOR EACH ROW
    EXECUTE FUNCTION bng.reject_unaudited_project_delete();
